package vn.aujunpeak.assist;

import android.app.*; import android.content.*; import android.content.res.Configuration; import android.graphics.*; import android.graphics.drawable.GradientDrawable; import android.os.*; import android.provider.Settings; import android.view.*; import android.view.inputmethod.InputMethodManager; import android.widget.*; import java.util.*;

public class OverlayService extends Service {
 WindowManager wm; final Handler h=new Handler(Looper.getMainLooper()); final ArrayList<View> windows=new ArrayList<>();
 View bubble,panel,stats,cursor; Cross cross; android.content.SharedPreferences prefs; boolean unlocked=false, telemetry=false;
 long lastWall=0,lastCpu=0; float cpu=0; int battery=0; float ram=0; final ArrayList<Float> history=new ArrayList<>(); TextView metrics; Chart chart;
 int accent=Color.rgb(102,234,207); int size=28,ox=0,oy=0,style=0; boolean rotate=false,glow=true;
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 int sw(){return getResources().getDisplayMetrics().widthPixels;} int sh(){return getResources().getDisplayMetrics().heightPixels;}
 @Override public void onCreate(){super.onCreate();wm=(WindowManager)getSystemService(WINDOW_SERVICE);prefs=getSharedPreferences("assist",0);size=prefs.getInt("size",28);ox=prefs.getInt("ox",0);oy=prefs.getInt("oy",0);style=prefs.getInt("style",0);rotate=prefs.getBoolean("rotate",false);glow=prefs.getBoolean("glow",true);startForeground(11,notification(this,"Nút nổi đang hoạt động",OverlayService.class));h.post(sample);}
 static Notification notification(android.content.Context c,String text,Class<?> cls){NotificationManager nm=(NotificationManager)c.getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("assist","Aujunpeak Assist",NotificationManager.IMPORTANCE_LOW));Intent stop=new Intent(c,cls).setAction("STOP");PendingIntent pi=PendingIntent.getService(c,7,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(c,"assist").setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle("Aujunpeak Assist").setContentText(text).setOngoing(true).addAction(new Notification.Action.Builder(null,"Dừng",pi).build()).build();}
 @Override public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){stopSelf();return START_NOT_STICKY;} if(!Settings.canDrawOverlays(this)){stopSelf();return START_NOT_STICKY;}if(windows.isEmpty())login();return START_NOT_STICKY;}
 GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));d.setStroke(dp(1),0xff59616c);return d;}
 TextView text(String s,int sp){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(sp);t.setPadding(dp(8),dp(6),dp(8),dp(6));return t;}
 LinearLayout box(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(12),dp(12),dp(12),dp(12));l.setBackground(bg(0xf51b2028,24));return l;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(13);b.setAllCaps(false);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff343f4c));b.setOnClickListener(v->r.run());return b;}
 void add(View v,int w,int height,int gravity,boolean input){WindowManager.LayoutParams p=new WindowManager.LayoutParams(w,height,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,(input?0:WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE)|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);p.gravity=gravity;try{wm.addView(v,p);windows.add(v);v.setAlpha(0);v.setScaleX(.9f);v.setScaleY(.9f);v.animate().alpha(1).scaleX(1).scaleY(1).setDuration(240).start();}catch(RuntimeException e){Toast.makeText(this,"Không thể hiển thị: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 void remove(View v){if(v!=null&&windows.remove(v)){try{wm.removeView(v);}catch(IllegalArgumentException ignored){}}}
 void closePanel(){remove(panel);panel=null;}
 void login(){LinearLayout l=box();l.setBackground(bg(Color.BLACK,22));l.addView(text("AUJUNPEAK · ĐĂNG NHẬP",18));EditText key=new EditText(this);key.setTextColor(Color.WHITE);key.setHintTextColor(0xff929ba8);key.setSingleLine(true);key.setHint("Nhập key");key.setInputType(129);l.addView(key);TextView err=text("",12);l.addView(err);l.addView(button("Đăng nhập",()->{if(!key.getText().toString().equals("havanhuan")){err.setText("Key không đúng");return;}((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(key.getWindowToken(),0);remove(l);unlocked=true;showBubble();}));l.addView(button("Đóng",this::stopSelf));add(l,Math.min(dp(330),sw()-dp(24)),-2,Gravity.CENTER,true);}
 void showBubble(){ImageView b=new ImageView(this);b.setImageResource(vn.aujunpeak.assist.R.drawable.bubble);b.setContentDescription("Mở AssistiveTouch; kéo để di chuyển");bubble=b;add(b,dp(58),dp(58),Gravity.TOP|Gravity.LEFT,false);WindowManager.LayoutParams p=(WindowManager.LayoutParams)b.getLayoutParams();p.x=Math.min(prefs.getInt("bx",12),Math.max(0,sw()-dp(58)));p.y=Math.min(prefs.getInt("by",180),Math.max(0,sh()-dp(58)));wm.updateViewLayout(b,p);drag(b,this::menu);}
 void drag(View v,Runnable click){v.setOnTouchListener(new View.OnTouchListener(){float x,y;int px,py;boolean moved;public boolean onTouch(View a,MotionEvent e){WindowManager.LayoutParams p=(WindowManager.LayoutParams)v.getLayoutParams();switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:x=e.getRawX();y=e.getRawY();px=p.x;py=p.y;moved=false;return true;case MotionEvent.ACTION_MOVE:float dx=e.getRawX()-x,dy=e.getRawY()-y;if(Math.abs(dx)+Math.abs(dy)>dp(6))moved=true;p.x=Math.max(0,Math.min(sw()-v.getWidth(),px+(int)dx));p.y=Math.max(0,Math.min(sh()-v.getHeight(),py+(int)dy));wm.updateViewLayout(v,p);return true;case MotionEvent.ACTION_UP:if(!moved&&click!=null)click.run();if(v==bubble)prefs.edit().putInt("bx",p.x).putInt("by",p.y).apply();return true;}return false;}});}
 void menu(){if(panel!=null){closePanel();return;}LinearLayout l=box();panel=l;l.addView(text("AUJUNPEAK ASSIST",14));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER);top.addView(tile("Hình ảnh","image",this::capture));l.addView(top);LinearLayout mid=new LinearLayout(this);mid.addView(tile("FPS","chart",this::toggleStats));mid.addView(tile("Thiết bị","phone",this::device));mid.addView(tile("Điều khiển","sliders",this::controls));l.addView(mid);LinearLayout bottom=new LinearLayout(this);bottom.setGravity(Gravity.CENTER);bottom.addView(tile("Sensitivity Touch","touch",this::touch));bottom.addView(tile("Tâm ảo","cross",this::crossPanel));l.addView(bottom);l.addView(button("Đóng menu",this::closePanel));add(l,Math.min(dp(350),sw()-dp(16)),-2,Gravity.CENTER,false);}
 View tile(String label,String glyph,Runnable action){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setGravity(Gravity.CENTER);l.setPadding(0,dp(8),0,dp(8));Icon icon=new Icon(glyph);l.addView(icon,new LinearLayout.LayoutParams(dp(42),dp(42)));TextView t=text(label,11);t.setGravity(Gravity.CENTER);l.addView(t);l.setLayoutParams(new LinearLayout.LayoutParams(0,-2,1));l.setOnClickListener(v->action.run());l.setContentDescription(label);return l;}
 LinearLayout side(String title,boolean right){closePanel();LinearLayout content=box();content.addView(text(title,18));content.addView(button("Đóng",this::closePanel));ScrollView scroll=new ScrollView(this);scroll.addView(content);panel=scroll;add(scroll,Math.min(dp(300),sw()-dp(60)),Math.min(sh()-dp(48),dp(580)),Gravity.TOP|(right?Gravity.RIGHT:Gravity.LEFT),true);scroll.setTranslationX(right?dp(300):-dp(300));scroll.animate().translationX(0).setDuration(260).start();return content;}
 interface Change{void set(int n);} void slider(LinearLayout l,String title,int min,int max,int value,Change change){TextView t=text(title+": "+value,13);l.addView(t);SeekBar b=new SeekBar(this);b.setMax(max-min);b.setProgress(Math.max(0,Math.min(max-min,value-min)));b.setProgressTintList(android.content.res.ColorStateList.valueOf(accent));l.addView(b);b.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){t.setText(title+": "+(p+min));change.set(p+min);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});}
 void crossPanel(){LinearLayout l=side("TÂM ẢO",true);if(cross==null){cross=new Cross();add(cross,dp(240),dp(240),Gravity.CENTER,false);WindowManager.LayoutParams p=(WindowManager.LayoutParams)cross.getLayoutParams();p.flags|=WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE;wm.updateViewLayout(cross,p);positionCross();}Cross preview=new Cross();l.addView(preview,new LinearLayout.LayoutParams(-1,dp(110)));String[] names={"Dấu cộng","Vòng tròn","Chấm","Bốn góc","Vòng + tâm","Chữ X"};Spinner types=new Spinner(this);types.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accent));types.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));types.setSelection(style);l.addView(types);types.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){style=n;}public void onNothingSelected(android.widget.AdapterView<?> p){}});
 slider(l,"Kích thước",4,80,size,n->size=n);slider(l,"Ngang",-sw()/2+dp(120),sw()/2-dp(120),ox,n->{ox=n;positionCross();});slider(l,"Dọc",-sh()/2+dp(120),sh()/2-dp(120),oy,n->{oy=n;positionCross();});Switch spin=new Switch(this);spin.setText("Xoay");spin.setTextColor(-1);spin.setChecked(rotate);spin.setOnCheckedChangeListener((b,c)->rotate=c);l.addView(spin);Switch light=new Switch(this);light.setText("Phát sáng");light.setTextColor(-1);light.setChecked(glow);light.setOnCheckedChangeListener((b,c)->glow=c);l.addView(light);l.addView(button("Đổi màu",()->{accent=accent==Color.RED?Color.CYAN:accent==Color.CYAN?Color.GREEN:Color.RED;}));l.addView(button("Lưu",()->{prefs.edit().putInt("size",size).putInt("ox",ox).putInt("oy",oy).putInt("style",style).putBoolean("rotate",rotate).putBoolean("glow",glow).apply();closePanel();success("Đã lưu tâm ảo");}));l.addView(button("Ẩn tâm",()->{remove(cross);cross=null;closePanel();}));}
 void positionCross(){if(cross!=null){WindowManager.LayoutParams p=(WindowManager.LayoutParams)cross.getLayoutParams();p.x=ox;p.y=oy;wm.updateViewLayout(cross,p);}}
 void touch(){LinearLayout l=side("VỊ TRÍ CON TRỎ",false);l.addView(text("Lưu vị trí tham chiếu. Không thay đổi độ nhạy cảm ứng của game.",12));if(cursor!=null)remove(cursor);TextView pointer=text("➤",26);cursor=pointer;add(pointer,dp(48),dp(48),Gravity.TOP|Gravity.LEFT,false);WindowManager.LayoutParams p=(WindowManager.LayoutParams)pointer.getLayoutParams();p.x=prefs.getInt("cx",sw()/2);p.y=prefs.getInt("cy",sh()/2);wm.updateViewLayout(pointer,p);drag(pointer,null);slider(l,"X (px)",0,sw()-dp(48),p.x,n->{p.x=n;wm.updateViewLayout(pointer,p);});slider(l,"Y (px)",0,sh()-dp(48),p.y,n->{p.y=n;wm.updateViewLayout(pointer,p);});l.addView(button("Lưu và ẩn",()->{prefs.edit().putInt("cx",p.x).putInt("cy",p.y).apply();remove(pointer);cursor=null;closePanel();success("Đã lưu vị trí con trỏ");}));}
 void controls(){LinearLayout l=side("ĐIỀU KHIỂN",false);l.addView(text("Hồ sơ tham chiếu — Android không cho app thường ép FPS/DPI của game.",13));EditText fps=new EditText(this);fps.setTextColor(-1);fps.setInputType(2);fps.setHint("FPS mục tiêu 30–240");fps.setText(""+prefs.getInt("fps",60));l.addView(fps);EditText dpi=new EditText(this);dpi.setTextColor(-1);dpi.setInputType(2);dpi.setText(""+prefs.getInt("dpi",getResources().getDisplayMetrics().densityDpi));l.addView(dpi);l.addView(text("DPI mong muốn 120–960\n"+Build.MANUFACTURER+" "+Build.MODEL+"\n"+sw()+" × "+sh()+" px · "+getResources().getDisplayMetrics().densityDpi+" DPI thực tế",13));l.addView(button("Lưu hồ sơ",()->{try{int f=Integer.parseInt(fps.getText().toString()),d=Integer.parseInt(dpi.getText().toString());if(f<30||f>240||d<120||d>960)throw new NumberFormatException();prefs.edit().putInt("fps",f).putInt("dpi",d).apply();success("Đã lưu hồ sơ tham chiếu");}catch(NumberFormatException e){success("Nhập FPS 30–240; DPI 120–960");}}));l.addView(button("Dừng ứng dụng",this::stopSelf));}
 void toggleStats(){closePanel();if(stats!=null){remove(stats);stats=null;return;}LinearLayout l=box();l.addView(text("GIÁM SÁT · FPS GAME: không có quyền đo",12));LinearLayout row=new LinearLayout(this);for(String name:new String[]{"RAM máy","CPU app","Pin"}){LinearLayout card=box();TextView t=text(name,12);card.addView(t);Chart c=new Chart(name);card.addView(c,new LinearLayout.LayoutParams(-1,dp(55)));row.addView(card,new LinearLayout.LayoutParams(0,-2,1));}l.addView(row);l.addView(button("Ẩn biểu đồ",()->{remove(stats);stats=null;}));stats=l;add(l,Math.min(dp(540),sw()-dp(16)),-2,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL,false);}
 void device(){LinearLayout l=side("THIẾT BỊ",false);FrameLayout phone=new FrameLayout(this);ImageView img=new ImageView(this);img.setImageResource(R.drawable.phone);img.setScaleType(ImageView.ScaleType.FIT_CENTER);phone.addView(img,new FrameLayout.LayoutParams(-1,-1));metrics=text("",13);metrics.setGravity(Gravity.CENTER);FrameLayout.LayoutParams mp=new FrameLayout.LayoutParams(-1,-1);mp.setMargins(dp(34),dp(30),dp(34),dp(30));phone.addView(metrics,mp);l.addView(phone,new LinearLayout.LayoutParams(-1,dp(350)));String path=prefs.getString("lastCapture",null);if(path!=null){android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeFile(path);if(bitmap!=null){ImageView shot=new ImageView(this);shot.setImageBitmap(bitmap);shot.setAdjustViewBounds(true);l.addView(text("Ảnh chụp gần nhất",12));l.addView(shot,new LinearLayout.LayoutParams(-1,dp(140)));}}l.addView(text("Game đang chơi: không truy cập dữ liệu ứng dụng khác. Dùng Hình ảnh để chụp preview màn hình với sự đồng ý của bạn.",12));}
 void capture(){closePanel();try{startActivity(new Intent(this,CaptureActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}catch(RuntimeException e){success("Không mở được chụp màn hình");}}
 void success(String message){TextView t=text("✓  "+message,13);t.setTextColor(0xff65e5a3);t.setBackground(bg(0xf51b2521,14));add(t,-2,-2,Gravity.TOP|Gravity.LEFT,false);WindowManager.LayoutParams p=(WindowManager.LayoutParams)t.getLayoutParams();p.y=dp(44);wm.updateViewLayout(t,p);h.postDelayed(()->{if(windows.contains(t))t.animate().alpha(0).setDuration(450).withEndAction(()->remove(t)).start();},2550);}
 final Runnable sample=new Runnable(){public void run(){ActivityManager.MemoryInfo mi=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(mi);ram=100f*(mi.totalMem-mi.availMem)/mi.totalMem;Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(b!=null)battery=Math.round(100f*b.getIntExtra(BatteryManager.EXTRA_LEVEL,0)/Math.max(1,b.getIntExtra(BatteryManager.EXTRA_SCALE,100)));long now=SystemClock.elapsedRealtime(),used=android.os.Process.getElapsedCpuTime();if(lastWall>0)cpu=Math.min(100,100f*(used-lastCpu)/Math.max(1,now-lastWall)/Runtime.getRuntime().availableProcessors());lastWall=now;lastCpu=used;history.add(ram);if(history.size()>40)history.remove(0);if(metrics!=null)metrics.setText(Build.MODEL+"\n\nRAM máy "+Math.round(ram)+"%\nCPU app "+String.format(java.util.Locale.US,"%.1f",cpu)+"%\nPin "+battery+"%\n\n"+sw()+" × "+sh());h.postDelayed(this,1000);}};
 class Chart extends View{Paint p=new Paint(3);String kind;ArrayList<Float> values=new ArrayList<>();long tick=0;Chart(String k){super(OverlayService.this);kind=k;setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){super.onDraw(c);float val=kind.equals("RAM máy")?ram:kind.equals("CPU app")?cpu:battery;if(SystemClock.elapsedRealtime()-tick>800){values.add(val);if(values.size()>35)values.remove(0);tick=SystemClock.elapsedRealtime();}p.setColor(accent);p.setTextSize(dp(14));p.setStyle(Paint.Style.FILL);c.drawText(String.format(java.util.Locale.US,"%.1f%%",val),dp(4),dp(17),p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1.5f));Path path=new Path();for(int i=0;i<values.size();i++){float x=(float)i*getWidth()/34,y=getHeight()-(getHeight()-dp(24))*values.get(i)/100;if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,p);postInvalidateDelayed(500);}}
 class Cross extends View{Paint p=new Paint(3);Cross(){super(OverlayService.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){float x=getWidth()/2f,y=getHeight()/2f,r=dp(size)/2f;c.save();if(rotate)c.rotate((SystemClock.uptimeMillis()%4000)*.09f,x,y);p.setColor(accent);p.setStrokeWidth(dp(2));p.setStyle(Paint.Style.STROKE);p.clearShadowLayer();if(glow)p.setShadowLayer(dp(7),0,0,accent);if(style==0||style==4){c.drawLine(x-r,y,x+r,y,p);c.drawLine(x,y-r,x,y+r,p);}if(style==1||style==4)c.drawCircle(x,y,r,p);if(style==2){p.setStyle(Paint.Style.FILL);c.drawCircle(x,y,Math.max(dp(2),r/5),p);}if(style==3){for(int i=0;i<4;i++){c.save();c.rotate(i*90,x,y);c.drawLine(x-r,y-r,x-r/2,y-r,p);c.drawLine(x-r,y-r,x-r,y-r/2,p);c.restore();}}if(style==5){c.drawLine(x-r,y-r,x+r,y+r,p);c.drawLine(x-r,y+r,x+r,y-r,p);}c.restore();postInvalidateDelayed(33);}}
 class Icon extends View{String type;Paint p=new Paint(3);Icon(String t){super(OverlayService.this);type=t;}protected void onDraw(Canvas raw){Canvas c=raw;c.save();c.scale(getWidth()/48f,getHeight()/48f);p.setColor(-1);p.setStrokeWidth(3);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);p.setStyle(Paint.Style.STROKE);if(type.equals("cross")){c.drawCircle(24,24,15,p);c.drawLine(24,3,24,14,p);c.drawLine(24,34,24,45,p);c.drawLine(3,24,14,24,p);c.drawLine(34,24,45,24,p);}else if(type.equals("phone")){c.drawRoundRect(12,3,36,45,6,6,p);c.drawLine(20,8,28,8,p);}else if(type.equals("sliders")){c.drawLine(4,14,44,14,p);c.drawLine(4,34,44,34,p);p.setStyle(Paint.Style.FILL);c.drawCircle(31,14,5,p);c.drawCircle(16,34,5,p);}else if(type.equals("image")){c.drawRoundRect(4,6,44,42,5,5,p);c.drawCircle(33,16,4,p);Path a=new Path();a.moveTo(5,34);a.lineTo(17,22);a.lineTo(28,35);a.lineTo(35,28);a.lineTo(43,36);c.drawPath(a,p);}else if(type.equals("chart")){c.drawRoundRect(4,5,44,37,4,4,p);Path a=new Path();a.moveTo(8,26);a.lineTo(15,26);a.lineTo(21,13);a.lineTo(28,31);a.lineTo(34,22);a.lineTo(40,22);c.drawPath(a,p);c.drawLine(20,43,28,43,p);}else{c.drawArc(6,3,42,39,185,170,false,p);c.drawArc(13,10,35,32,185,170,false,p);c.drawRoundRect(20,20,27,43,4,4,p);c.drawArc(15,27,40,47,0,160,false,p);}c.restore();}}
 @Override public void onConfigurationChanged(Configuration c){super.onConfigurationChanged(c);closePanel();remove(stats);stats=null;remove(cursor);cursor=null;if(bubble!=null){WindowManager.LayoutParams p=(WindowManager.LayoutParams)bubble.getLayoutParams();p.x=Math.max(0,Math.min(p.x,sw()-dp(58)));p.y=Math.max(0,Math.min(p.y,sh()-dp(58)));wm.updateViewLayout(bubble,p);}ox=Math.max(-sw()/2+dp(120),Math.min(ox,sw()/2-dp(120)));oy=Math.max(-sh()/2+dp(120),Math.min(oy,sh()/2-dp(120)));positionCross();}
 @Override public void onDestroy(){h.removeCallbacksAndMessages(null);for(View v:new ArrayList<>(windows))remove(v);super.onDestroy();} @Override public IBinder onBind(Intent i){return null;}
}
